import React, { useState } from 'react'
import { Sparkles, TrendingUp, TrendingDown, AlertCircle, CheckCircle2, Info } from 'lucide-react'
import { Button, Alert, Input } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'

const ScoreBar = ({ label, score, color = '#6655ee', max = 100 }) => (
  <div className="analyzer-score-row">
    <span>{label}</span>
    <div className="analyzer-bar-wrap">
      <div className="analyzer-bar-fill" style={{ width: `${(score / max) * 100}%`, background: color }} />
    </div>
    <strong>{score != null ? score : '—'}</strong>
  </div>
)

const SCORE_COLOR = (score) => score >= 70 ? '#2da96d' : score >= 40 ? '#ec7c45' : '#e05261'

export const ProfileAnalyzer = () => {
  const [targetRole, setTargetRole] = useState('')
  const [result, setResult] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const analyze = async () => {
    setLoading(true)
    setError('')
    setResult(null)
    try {
      const res = await careerAgentAPI.analyzeProfile(targetRole)
      if (res?.success) setResult(res.data)
      else setError('Profile analysis failed. Please try again.')
    } catch (err) {
      setError(err?.message || 'Profile analysis unavailable.')
    } finally {
      setLoading(false)
    }
  }

  const analysis = result?.analysis || {}
  const scores = result?.scores || analysis.scores || {}

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">AI PROFILE ANALYZER</span>
        <h2>Get a full breakdown of your career readiness</h2>
        <p className="career-muted">Analyzes your education, skills, projects, experience, certifications, GitHub and LinkedIn presence against your target role.</p>
      </div>

      <div className="career-role-input">
        <Input
          label="Target Role (optional — leave blank to use your saved preference)"
          value={targetRole}
          onChange={(e) => setTargetRole(e.target.value)}
          placeholder="e.g. AI/ML Engineer, Data Analyst, Full Stack Developer"
        />
        <Button variant="nav" onClick={analyze} loading={loading}>
          <Sparkles size={15} /> Analyze My Profile
        </Button>
      </div>

      {error && <Alert type="error" message={error} />}

      {result && (
        <div className="profile-analyzer-result">
          {/* Overall score hero */}
          <div className="analyzer-hero" style={{ borderColor: SCORE_COLOR(scores.overall) }}>
            <div className="analyzer-hero-score">
              <strong style={{ color: SCORE_COLOR(scores.overall) }}>{scores.overall ?? '—'}</strong>
              <span>/100</span>
            </div>
            <div>
              <h3>Overall Career Readiness Score</h3>
              <p className="career-disclaimer"><AlertCircle size={13} /> {result.disclaimer}</p>
              {result.fallback && <p className="career-muted"><Info size={13} /> Scored using local deterministic model (AI service offline).</p>}
            </div>
          </div>

          {/* Score breakdown */}
          <div className="analyzer-breakdown">
            <span className="section-label">SCORE BREAKDOWN</span>
            <div className="analyzer-bars">
              <ScoreBar label="Skills" score={scores.skills} color="#6655ee" />
              <ScoreBar label="Projects" score={scores.projects} color="#2da96d" />
              <ScoreBar label="Experience" score={scores.experience} color="#ec7c45" />
              <ScoreBar label="GitHub Presence" score={scores.github} color="#117a72" />
              <ScoreBar label="LinkedIn Presence" score={scores.linkedin} color="#3b82f6" />
              <ScoreBar label="Certifications" score={scores.certifications} color="#e05261" />
            </div>
          </div>

          <div className="analyzer-columns">
            {/* Strengths */}
            <div className="analyzer-col">
              <span className="section-label"><TrendingUp size={13} color="#2da96d" /> STRENGTHS</span>
              {(analysis.strengths || []).length > 0
                ? (analysis.strengths || []).map((s) => (
                    <div key={s} className="analyzer-item good">
                      <CheckCircle2 size={14} color="#2da96d" /> {s}
                    </div>
                  ))
                : <p className="career-muted">Complete the AI Interview to see strengths.</p>
              }
            </div>

            {/* Weaknesses / skill gaps */}
            <div className="analyzer-col">
              <span className="section-label"><TrendingDown size={13} color="#e05261" /> AREAS TO IMPROVE</span>
              {(analysis.weaknesses || []).length > 0
                ? (analysis.weaknesses || []).map((w) => (
                    <div key={w} className="analyzer-item warn">
                      <AlertCircle size={14} color="#e05261" /> {w}
                    </div>
                  ))
                : <p className="career-muted">No critical weaknesses detected for this profile.</p>
              }
            </div>
          </div>

          {/* Missing information */}
          {(analysis.missingInfo || []).length > 0 && (
            <div className="analyzer-missing">
              <span className="section-label">MISSING INFORMATION</span>
              <ul>
                {(analysis.missingInfo || []).map((item, i) => (
                  <li key={i}><Info size={13} /> {item}</li>
                ))}
              </ul>
            </div>
          )}

          {/* Recommendations */}
          {(analysis.recommendations || []).length > 0 && (
            <div className="analyzer-recommendations">
              <span className="section-label">RECOMMENDED IMPROVEMENTS</span>
              {(analysis.recommendations || []).map((rec, i) => (
                <div key={i} className="analyzer-rec-item">
                  <span className="task-dot" /> {rec}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
}
