import React, { useState } from "react";
import { Button, Input, Card, Alert } from "../components/common";
import { Link } from "react-router-dom";
import {
  ArrowLeft,
  BrainCircuit,
  CheckCircle2,
  ArrowRight,
  Eye,
  EyeOff,
  Users,
  Building2,
  GraduationCap,
  Landmark,
} from "lucide-react";
import { AICPLogo } from "../components/AICPLogo";
import { ROUTES } from "../utils/constants";
import { useAuth } from "../context/AuthContext";
import { validateEmail, validateOTP, getErrorMessage } from "../utils/helpers";

const roles = [
  ["student", "Student", "Build skills and find opportunities", GraduationCap],
  ["industry", "Industry", "Hire and grow your team", Building2],
  ["academician", "Academician", "Teach, mentor and collaborate", Users],
  ["institution", "Institution", "Track campus outcomes", Landmark],
];

export const RegisterPage = () => {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    dateOfBirth: "",
    organization: "",
    password: "",
    confirmPassword: "",
    role: "student",
  });
  const [profile, setProfile] = useState({});
  const [otp, setOtp] = useState("");
  const [step, setStep] = useState("basic");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const { register, verifyRegistrationOTP } = useAuth();

  const handleBasicNext = (event) => {
    event.preventDefault();
    setError("");
    if (
      !form.name.trim() ||
      !validateEmail(form.email) ||
      !form.phone.trim() ||
      !form.dateOfBirth ||
      form.password.length < 6 ||
      form.password !== form.confirmPassword
    ) {
      setError(
        "Complete your name, email, phone, date of birth, and matching passwords.",
      );
      return;
    }
    setStep("additional");
  };

  const handleRequest = async (event) => {
    event.preventDefault();
    setError("");
    if (
      !form.name.trim() ||
      !validateEmail(form.email) ||
      form.password.length < 6 ||
      form.password !== form.confirmPassword ||
      !isProfileComplete(form.role, profile)
    ) {
      setError(
        `Complete all required ${form.role} profile fields and use matching passwords.`,
      );
      return;
    }
    setLoading(true);
    try {
      await register({
        ...form,
        profile: serializeProfile(form.role, profile),
      });
      setStep("otp");
      setSuccess("OTP sent to your email. Check your inbox.");
    } catch (err) {
      setError(getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (event) => {
    event.preventDefault();
    setError("");
    if (!validateOTP(otp)) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }
    setLoading(true);
    try {
      await verifyRegistrationOTP(form.email, otp);
      setSuccess("Registration complete. Redirecting...");
    } catch (err) {
      setError(getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page auth-register">
      <div className="auth-brand">
        <Link to={ROUTES.HOME}>
          <ArrowLeft size={17} /> Back to AICP
        </Link>
      </div>
      <div className="auth-layout">
        <div className="auth-intro">
          <AICPLogo />
          <span className="section-label">START YOUR JOURNEY</span>
          <h1>
            Create your account and <span>join AICP.</span>
          </h1>
          <p>
            Be part of a unified platform connecting students, industries,
            academicians and institutions.
          </p>
          <div className="auth-checks">
            <span>
              <CheckCircle2 size={17} /> Create your profile
            </span>
            <span>
              <CheckCircle2 size={17} /> Discover your pathway
            </span>
            <span>
              <CheckCircle2 size={17} /> Connect with the right people
            </span>
          </div>
        </div>
        <div className="auth-form-shell">
          <Card className="auth-card">
            <div className="auth-card-header">
              <div className="auth-card-icon">
                <BrainCircuit size={19} />
              </div>
              <div>
                <span className="section-label">CREATE ACCOUNT</span>
                <h1>Create your AICP account</h1>
              </div>
            </div>
            <p className="auth-card-subtitle">
              Fill in the details below to create your account.
            </p>
            <div className="registration-steps">
              <span className={step === "basic" ? "active" : "done"}>
                1 <small>Basic Information</small>
              </span>
              <i />
              <span
                className={
                  step === "additional"
                    ? "active"
                    : step === "otp"
                      ? "done"
                      : ""
                }
              >
                2 <small>Additional Details</small>
              </span>
              <i />
              <span className={step === "otp" ? "active" : ""}>
                3 <small>Verify Email</small>
              </span>
            </div>
            {error && (
              <Alert
                type="error"
                message={error}
                onClose={() => setError("")}
              />
            )}
            {success && (
              <Alert
                type="success"
                message={success}
                onClose={() => setSuccess("")}
              />
            )}
            {step === "basic" ? (
              <form onSubmit={handleBasicNext} className="space-y-4">
                <RoleChoice form={form} setForm={setForm} loading={loading} />
                <div className="profile-form-grid">
                  <Input
                    label="Full name"
                    value={form.name}
                    onChange={(event) =>
                      setForm({ ...form, name: event.target.value })
                    }
                    required
                    disabled={loading}
                  />
                  <Input
                    label="Email address"
                    type="email"
                    value={form.email}
                    onChange={(event) =>
                      setForm({ ...form, email: event.target.value })
                    }
                    required
                    disabled={loading}
                  />
                  <Input
                    label="Phone number"
                    value={form.phone}
                    onChange={(event) =>
                      setForm({ ...form, phone: event.target.value })
                    }
                    required
                    disabled={loading}
                  />
                  <PasswordInput
                    label="Password"
                    value={form.password}
                    onChange={(event) =>
                      setForm({ ...form, password: event.target.value })
                    }
                    visible={showPassword}
                    onToggle={() => setShowPassword((value) => !value)}
                    disabled={loading}
                  />
                  <PasswordInput
                    label="Confirm password"
                    value={form.confirmPassword}
                    onChange={(event) =>
                      setForm({ ...form, confirmPassword: event.target.value })
                    }
                    visible={showConfirmPassword}
                    onToggle={() => setShowConfirmPassword((value) => !value)}
                    disabled={loading}
                  />
                  <Input
                    label="Date of birth"
                    type="date"
                    value={form.dateOfBirth}
                    onChange={(event) =>
                      setForm({ ...form, dateOfBirth: event.target.value })
                    }
                    required
                    disabled={loading}
                  />
                </div>
                <Input
                  label="Institution / organization (optional)"
                  value={form.organization}
                  onChange={(event) =>
                    setForm({ ...form, organization: event.target.value })
                  }
                  disabled={loading}
                />
                <Button
                  type="submit"
                  variant="primary"
                  size="lg"
                  loading={loading}
                  className="w-full"
                >
                  Continue to additional details <ArrowRight size={16} />
                </Button>
              </form>
            ) : step === "additional" ? (
              <form onSubmit={handleRequest} className="space-y-4">
                <RoleProfileFields
                  role={form.role}
                  profile={profile}
                  setProfile={setProfile}
                  disabled={loading}
                />
                <Button
                  type="submit"
                  variant="primary"
                  size="lg"
                  loading={loading}
                  className="w-full"
                >
                  Send verification OTP <ArrowRight size={16} />
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  className="w-full"
                  onClick={() => setStep("basic")}
                >
                  Back to basic information
                </Button>
              </form>
            ) : (
              <form onSubmit={handleVerify} className="space-y-4">
                <p className="text-sm text-gray-600">
                  Enter the 6-digit OTP sent to <strong>{form.email}</strong>.
                </p>
                <Input
                  label="OTP code"
                  value={otp}
                  onChange={(event) =>
                    setOtp(event.target.value.replace(/\D/g, "").slice(0, 6))
                  }
                  inputMode="numeric"
                  maxLength="6"
                  required
                  disabled={loading}
                />
                <Button
                  type="submit"
                  variant="primary"
                  size="lg"
                  loading={loading}
                  className="w-full"
                >
                  Verify and create account
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  size="lg"
                  className="w-full"
                  onClick={() => setStep("additional")}
                >
                  Change details
                </Button>
              </form>
            )}
            <div className="auth-card-foot">
              <span>Already have an account?</span>
              <Link to={ROUTES.LOGIN}>
                Log in <ArrowRight size={14} />
              </Link>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

const roleFields = {
  student: [
    ["college", "Institute / college", "text"],
    ["department", "Department", "text"],
    ["graduationYear", "Graduation year", "number"],
    ["cgpa", "CGPA (0-10)", "number"],
    ["skills", "Skills (comma separated)", "text"],
  ],
  industry: [
    ["companyName", "Company name", "text"],
    ["industry", "Industry / domain", "text"],
    ["companySize", "Company size", "text"],
    ["headquarters", "Headquarters", "text"],
    ["website", "Company website (optional)", "url"],
  ],
  academician: [
    ["institution", "Institution", "text"],
    ["department", "Department", "text"],
    ["designation", "Designation", "text"],
    ["specialization", "Specialization (comma separated)", "text"],
  ],
  institution: [
    ["institutionName", "Institution name", "text"],
    ["type", "Institution type", "text"],
    ["location", "Location", "text"],
    ["accreditation", "Accreditation (optional)", "text"],
    ["departments", "Departments (comma separated)", "text"],
  ],
};

const serializeProfile = (role, profile) => {
  const arrayFields =
    role === "student"
      ? ["skills"]
      : role === "academician"
        ? ["specialization"]
        : role === "institution"
          ? ["departments"]
          : [];
  return Object.fromEntries(
    Object.entries(profile).map(([key, value]) => [
      key,
      arrayFields.includes(key)
        ? String(value)
            .split(",")
            .map((item) => item.trim())
            .filter(Boolean)
        : value,
    ]),
  );
};

const isProfileComplete = (role, profile) => {
  const required = roleFields[role]
    .filter(([key]) => !["website", "accreditation"].includes(key))
    .map(([key]) => key);
  return required.every((key) => {
    const value = profile[key];
    return Array.isArray(value)
      ? value.length > 0
      : String(value ?? "").trim().length > 0;
  });
};

const RoleChoice = ({ form, setForm, loading }) => (
  <label className="block text-sm font-medium text-gray-700">
    <span>I am signing up as</span>
    <div className="role-choice-grid">
      {roles.map(([value, label, copy, Icon]) => (
        <label
          className={
            form.role === value ? "role-choice selected" : "role-choice"
          }
          key={value}
        >
          <input
            type="radio"
            name="role"
            value={value}
            checked={form.role === value}
            onChange={() => {
              setForm({ ...form, role: value });
            }}
            disabled={loading}
          />
          <Icon size={18} />
          <strong>{label}</strong>
          <small>{copy}</small>
        </label>
      ))}
    </div>
  </label>
);

const RoleProfileFields = ({ role, profile, setProfile, disabled }) => (
  <div className="registration-profile-fields">
    <span className="section-label">ROLE PROFILE</span>
    <p className="text-sm text-gray-600">
      These details power your role workspace and recommendations.
    </p>
    <div className="profile-form-grid">
      {roleFields[role].map(([key, label, type]) => (
        <Input
          key={key}
          label={label}
          type={type}
          value={profile[key] || ""}
          onChange={(event) =>
            setProfile((current) => ({ ...current, [key]: event.target.value }))
          }
          required={!["website", "accreditation"].includes(key)}
          disabled={disabled}
          min={key === "cgpa" ? "0" : undefined}
          max={key === "cgpa" ? "10" : undefined}
          minLength={key === "skills" ? "2" : undefined}
        />
      ))}
    </div>
  </div>
);

const PasswordInput = ({
  label,
  value,
  onChange,
  visible,
  onToggle,
  disabled,
}) => (
  <div className="password-field-group">
    <label
      className="password-label-row"
      htmlFor={`register-${label.toLowerCase().replaceAll(" ", "-")}`}
    >
      {label} *
    </label>
    <div className="password-control">
      <input
        id={`register-${label.toLowerCase().replaceAll(" ", "-")}`}
        type={visible ? "text" : "password"}
        value={value}
        onChange={onChange}
        required
        disabled={disabled}
        placeholder={
          label === "Password" ? "Create a password" : "Confirm your password"
        }
      />
      <button
        type="button"
        onClick={onToggle}
        aria-label={
          visible
            ? `Hide ${label.toLowerCase()}`
            : `Show ${label.toLowerCase()}`
        }
      >
        {visible ? <EyeOff size={16} /> : <Eye size={16} />}
      </button>
    </div>
  </div>
);
