import React, { useEffect, useState } from 'react'
import { Briefcase, FileUp, Pencil, Plus, Trash2 } from 'lucide-react'
import { Alert, Button, Input } from './common'
import { assessmentAPI, opportunitiesAPI } from '../services/api'

const emptyOpportunity = { title: '', type: 'internship', description: '', requiredSkills: '', location: 'Remote', deadline: '' }
const emptyTest = { title: '', description: '' }
const newQuestion = () => ({ question: '', options: ['', ''], correctAnswer: 0, explanation: '' })

const QuestionBlock = ({ item, index, onChange, onRemove }) => {
  const change = (key, value) => onChange({ ...item, [key]: value })
  return <fieldset className="question-editor">
    <div className="question-editor-heading"><h3>Question {index + 1}</h3>{index > 0 && <button type="button" className="question-remove" onClick={onRemove}><Trash2 size={13} /> Remove</button>}</div>
    <Input label="Question text" value={item.question} onChange={(event) => change('question', event.target.value)} required placeholder="Which runtime executes JavaScript on servers?" />
    <div className="question-options"><span className="question-field-label">Options</span>{item.options.map((option, optionIndex) => <div className="question-option-row" key={optionIndex}><Input label={`Option ${optionIndex + 1}`} value={option} onChange={(event) => change('options', item.options.map((value, indexValue) => indexValue === optionIndex ? event.target.value : value))} required placeholder={`Answer option ${optionIndex + 1}`} /><button type="button" className="question-remove" disabled={item.options.length <= 2} onClick={() => change('options', item.options.filter((_, valueIndex) => valueIndex !== optionIndex))}>Remove</button></div>)}<Button type="button" size="sm" variant="outline" onClick={() => change('options', [...item.options, ''])}><Plus size={14} /> Add option</Button></div>
    <label className="profile-field">Correct option<select value={item.correctAnswer} onChange={(event) => change('correctAnswer', Number(event.target.value))}>{item.options.map((_, optionIndex) => <option value={optionIndex} key={optionIndex}>Option {optionIndex + 1}</option>)}</select></label>
    <Input label="Explanation (optional)" value={item.explanation} onChange={(event) => change('explanation', event.target.value)} placeholder="Explain the answer" />
  </fieldset>
}

export const IndustryPostings = () => {
  const [opportunity, setOpportunity] = useState(emptyOpportunity)
  const [test, setTest] = useState(emptyTest)
  const [questions, setQuestions] = useState([newQuestion()])
  const [questionFile, setQuestionFile] = useState(null)
  const [postings, setPostings] = useState([])
  const [message, setMessage] = useState('')
  const [loading, setLoading] = useState(false)
  const [editingId, setEditingId] = useState(null)

  useEffect(() => { opportunitiesAPI.getOpportunities({ limit: 30 }).then((response) => setPostings(response?.data?.items || [])).catch(() => {}) }, [])
  const update = (setter) => (event) => setter((current) => ({ ...current, [event.target.name]: event.target.value }))
  const updateQuestion = (index, value) => setQuestions((current) => current.map((item, itemIndex) => itemIndex === index ? value : item))

  const publishOpportunity = async (event) => {
    event.preventDefault(); setLoading(true)
    try {
      const payload = { ...opportunity, requiredSkills: opportunity.requiredSkills.split(',').map((item) => item.trim()).filter(Boolean) }
      if (editingId) {
        const response = await opportunitiesAPI.updateOpportunity(editingId, payload)
        setPostings((current) => current.map((item) => item._id === editingId ? response?.data?.opportunity : item))
        setMessage('Opportunity updated successfully.')
      } else {
        const response = await opportunitiesAPI.createOpportunity(payload)
        setPostings((current) => [response?.data?.opportunity, ...current].filter(Boolean))
        setMessage('Opportunity published for students.')
      }
      setOpportunity(emptyOpportunity); setEditingId(null)
    } catch (error) { setMessage(error?.message || 'Opportunity could not be saved.') } finally { setLoading(false) }
  }

  const editPosting = (item) => { setEditingId(item._id); setOpportunity({ ...emptyOpportunity, ...item, deadline: item.deadline ? new Date(item.deadline).toISOString().slice(0, 10) : '', requiredSkills: (item.requiredSkills || []).join(', ') }); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const deletePosting = async (id) => {
    if (!window.confirm('Delete this opportunity? Existing applications will also be removed.')) return
    setLoading(true)
    try {
      await opportunitiesAPI.deleteOpportunity(id)
      setPostings((current) => current.filter((item) => item._id !== id))
      if (editingId === id) {
        setEditingId(null)
        setOpportunity(emptyOpportunity)
      }
      setMessage('Opportunity deleted successfully.')
    } catch (error) {
      setMessage(error?.response?.data?.message || error?.message || 'Opportunity could not be deleted.')
    } finally {
      setLoading(false)
    }
  }

  const publishTest = async (event) => {
    event.preventDefault(); setLoading(true)
    try {
      if (!test.title.trim()) throw new Error('Test title is required.')
      if (questionFile) { const data = new FormData(); data.append('title', test.title); data.append('description', test.description); data.append('type', 'technical'); data.append('file', questionFile); await assessmentAPI.importAssessment(data) } else {
        const prepared = questions.map((item) => ({ ...item, question: item.question.trim(), options: item.options.map((option) => option.trim()).filter(Boolean) }))
        if (prepared.some((item) => !item.question || item.options.length < 2)) throw new Error('Complete every question and add at least two options.')
        await assessmentAPI.createAssessment({ ...test, type: 'technical', questions: prepared })
      }
      setTest(emptyTest); setQuestions([newQuestion()]); setQuestionFile(null); setMessage('Mock test published. Students can see it in Assessment Center.')
    } catch (error) { setMessage(error?.message || 'Mock test could not be published.') } finally { setLoading(false) }
  }

  return <div className="workspace-page role-page">
    <header className="role-page-header"><div><span className="section-label">INDUSTRY POSTINGS</span><h1>Publish opportunities and assessments</h1><p>Create internships, jobs, and student mock tests from one operations space.</p></div><Briefcase size={28} /></header>
    {message && <Alert type="info" message={message} />}
    <form className="role-form" onSubmit={publishOpportunity}><h2>{editingId ? 'Edit internship or job' : 'New internship or job'}</h2><Input label="Title" name="title" value={opportunity.title} onChange={update(setOpportunity)} required placeholder="Backend Developer Intern" /><label className="profile-field">Type<select name="type" value={opportunity.type} onChange={update(setOpportunity)}><option value="internship">Internship</option><option value="job">Job</option></select></label><Input label="Description" name="description" value={opportunity.description} onChange={update(setOpportunity)} required placeholder="Describe the work and expected outcome" /><Input label="Required skills" name="requiredSkills" value={opportunity.requiredSkills} onChange={update(setOpportunity)} placeholder="Node.js, MongoDB, REST APIs" /><Input label="Location" name="location" value={opportunity.location} onChange={update(setOpportunity)} placeholder="Remote" /><Input label="Application deadline" name="deadline" type="date" value={opportunity.deadline} onChange={update(setOpportunity)} required /><div className="form-actions"><Button type="submit" loading={loading}>{editingId ? <Pencil size={16} /> : <Plus size={16} />} {editingId ? 'Update opportunity' : 'Publish opportunity'}</Button>{editingId && <Button type="button" variant="outline" onClick={() => { setEditingId(null); setOpportunity(emptyOpportunity) }}>Cancel</Button>}</div></form>
    <div className="role-table">{postings.map((item) => <article className="role-row" key={item._id}><div><strong>{item.title}</strong><small>{item.type} · {item.status} · Apply by {item.deadline ? new Date(item.deadline).toLocaleDateString() : 'No deadline'}</small></div><div className="role-row-actions"><Button size="sm" variant="outline" onClick={() => editPosting(item)}><Pencil size={14} /> Edit</Button><Button size="sm" variant="danger" loading={loading} onClick={() => deletePosting(item._id)}><Trash2 size={14} /> Delete</Button></div></article>)}{!postings.length && <p className="workspace-empty">No postings yet.</p>}</div>
    <form className="role-form question-bank-form" onSubmit={publishTest}><div className="question-bank-title"><div><span className="section-label">STUDENT ASSESSMENT</span><h2>Student mock test</h2></div><FileUp size={22} /></div><Input label="Test title" name="title" value={test.title} onChange={update(setTest)} required placeholder="Node.js screening test" /><Input label="Description" name="description" value={test.description} onChange={update(setTest)} placeholder="What students will demonstrate" />{questions.map((item, index) => <QuestionBlock key={index} item={item} index={index} onChange={(value) => updateQuestion(index, value)} onRemove={() => setQuestions((current) => current.filter((_, itemIndex) => itemIndex !== index))} />)}<Button type="button" variant="outline" onClick={() => setQuestions((current) => [...current, newQuestion()])}><Plus size={14} /> Add question</Button><Input label="Question bank file (optional)" type="file" accept=".csv,.json,.xlsx" onChange={(event) => setQuestionFile(event.target.files?.[0] || null)} /><Button type="submit" loading={loading}><FileUp size={16} /> Publish mock test</Button></form>
  </div>
}
