import React, { useEffect, useState } from 'react'
import { Briefcase, CheckCircle2, GraduationCap, Plus, Search, Users } from 'lucide-react'
import { Alert, Button, Input } from './common'
import { analyticsAPI, applicationAPI, assessmentAPI, collaborationAPI, documentAPI, learningAPI, opportunitiesAPI } from '../services/api'
import { IndustryPostings } from './IndustryPostings'

const itemsFrom = (response) => response?.data?.items || response?.data?.opportunities || []
const blankOpportunity = { title: '', type: 'internship', description: '', requiredSkills: '', preferredSkills: '', location: 'Remote', workMode: 'remote', duration: '', stipend: '', experienceRequired: 'Entry level', eligibility: '', openings: '1', deadline: '' }
const blankTest = { title: '', description: '', question: '', options: '', correctAnswer: '0' }

const blankQuestion = () => ({ question: '', options: ['', ''], correctAnswer: 0, explanation: '' })

const QuestionEditor = ({ question, index, onChange, onRemove, canRemove }) => {
  const updateQuestion = (field, value) => onChange({ ...question, [field]: value })
  const updateOption = (optionIndex, value) => {
    const options = [...question.options]
    options[optionIndex] = value
    updateQuestion('options', options)
  }
  const addOption = () => updateQuestion('options', [...question.options, ''])
  const removeOption = (optionIndex) => updateQuestion('options', question.options.filter((_, itemIndex) => itemIndex !== optionIndex))

  return <fieldset className="question-editor">
    <div className="question-editor-heading"><h3>Question {index + 1}</h3>{canRemove && <button type="button" className="question-remove" onClick={onRemove}>Remove</button>}</div>
    <Input label="Question text" value={question.question} onChange={(event) => updateQuestion('question', event.target.value)} required placeholder="Which runtime executes JavaScript on servers?" />
    <div className="question-options"><span className="question-field-label">Options</span>{question.options.map((option, optionIndex) => <div className="question-option-row" key={optionIndex}><Input label={`Option ${optionIndex + 1}`} value={option} onChange={(event) => updateOption(optionIndex, event.target.value)} required placeholder={`Answer option ${optionIndex + 1}`} /><button type="button" className="question-remove" onClick={() => removeOption(optionIndex)} disabled={question.options.length <= 2}>Remove</button></div>)}<Button type="button" size="sm" variant="outline" onClick={addOption}><Plus size={14} /> Add option</Button></div>
    <label className="profile-field">Correct option<select value={question.correctAnswer} onChange={(event) => updateQuestion('correctAnswer', Number(event.target.value))}>{question.options.map((_, optionIndex) => <option value={optionIndex} key={optionIndex}>Option {optionIndex + 1}</option>)}</select></label>
    <Input label="Explanation (optional)" value={question.explanation} onChange={(event) => updateQuestion('explanation', event.target.value)} placeholder="Explain why the answer is correct" />
  </fieldset>
}

export const RoleOperations = ({ role, view = 'dashboard' }) => {
  const [records, setRecords] = useState([])
  const [candidates, setCandidates] = useState([])
  const [form, setForm] = useState(blankOpportunity)
  const [test, setTest] = useState(blankTest)
  const [questions, setQuestions] = useState([blankQuestion()])
  const [message, setMessage] = useState('')
  const [loading, setLoading] = useState(false)
  const [selectedCandidate, setSelectedCandidate] = useState(null)
  const [rejectionReason, setRejectionReason] = useState('')
  const [questionBankFile, setQuestionBankFile] = useState(null)

  useEffect(() => {
    let active = true
    const load = async () => {
      try {
        if (role === 'industry') {
          const response = await opportunitiesAPI.getOpportunities({ limit: 30 })
          if (active) setRecords(itemsFrom(response))
        } else if (role === 'academician') {
          const [postings, collaborations] = await Promise.all([opportunitiesAPI.getOpportunities({ limit: 20 }), collaborationAPI.getCollaborations()])
          if (active) setRecords([...itemsFrom(postings), ...itemsFrom(collaborations)])
        } else if (role === 'institution') {
          const response = await analyticsAPI.getInstitution()
          if (active) setRecords(response?.data || {})
        }
      } catch (error) {
        if (active) setMessage(error?.message || 'Live data is unavailable.')
      }
    }
    load()
    return () => { active = false }
  }, [role])

  const update = (setter) => (event) => setter((current) => ({ ...current, [event.target.name]: event.target.value }))

  const publishOpportunity = async (event) => {
    event.preventDefault()
    setLoading(true)
    try {
      const response = await opportunitiesAPI.createOpportunity({ ...form, type: role === 'academician' ? 'project' : form.type, requiredSkills: form.requiredSkills.split(',').map((skill) => skill.trim()).filter(Boolean), preferredSkills: form.preferredSkills.split(',').map((skill) => skill.trim()).filter(Boolean), openings: Number(form.openings) || 1 })
      setRecords((current) => [response?.data?.opportunity, ...current].filter(Boolean))
      setForm(blankOpportunity)
      setMessage('Posting published and available for student applications.')
    } catch (error) {
      setMessage(error?.message || 'Posting could not be published.')
    } finally { setLoading(false) }
  }

  const publishMockTest = async (event) => {
    event.preventDefault()
    setLoading(true)
    try {
      if (questionBankFile) {
        const formData = new FormData()
        formData.append('title', test.title)
        formData.append('description', test.description)
        formData.append('type', 'technical')
        formData.append('file', questionBankFile)
        await assessmentAPI.importAssessment(formData)
      } else {
        const validQuestions = questions.map((question) => ({ ...question, options: question.options.map((option) => option.trim()).filter(Boolean) }))
        if (!validQuestions.length || validQuestions.some((question) => !question.question.trim() || question.options.length < 2)) throw new Error('Complete every question and add at least two options.')
        await assessmentAPI.createAssessment({ title: test.title, description: test.description, type: 'technical', questions: validQuestions })
      }
      setTest(blankTest)
      setQuestions([blankQuestion()])
      setQuestionBankFile(null)
      setMessage('Mock test published for students.')
    } catch (error) {
      setMessage(error?.message || 'Mock test could not be published.')
    } finally { setLoading(false) }
  }

  const rankApplicants = async (opportunityId) => {
    setLoading(true)
    try {
      const response = await opportunitiesAPI.rankCandidates(opportunityId)
      setCandidates(response?.data?.candidates || [])
    } catch (error) {
      setMessage(error?.message || 'Applicants could not be ranked.')
    } finally { setLoading(false) }
  }

  const updateApplication = async (id, status, feedback = '') => {
    setLoading(true)
    try {
      await applicationAPI.updateStatus(id, { status, feedback })
      setCandidates((current) => current.map((candidate) => candidate.applicationId === id ? { ...candidate, status, feedback } : candidate))
      setSelectedCandidate(null)
    } catch (error) {
      setMessage(error?.message || 'Application status could not be updated.')
    } finally { setLoading(false) }
  }

  const rejectSelected = async () => {
    if (!selectedCandidate || !rejectionReason.trim()) return setMessage('Add a reason before rejecting the application.')
    setLoading(true)
    try {
      await applicationAPI.reject(selectedCandidate.applicationId, { reason: rejectionReason.trim() })
      setCandidates((current) => current.map((candidate) => candidate.applicationId === selectedCandidate.applicationId ? { ...candidate, status: 'rejected', feedback: rejectionReason.trim() } : candidate))
      setSelectedCandidate(null)
      setRejectionReason('')
    } catch (error) { setMessage(error?.message || 'Application could not be rejected.') } finally { setLoading(false) }
  }

  const downloadResume = async (applicationId, fileName) => {
    try {
      const response = await documentAPI.downloadApplicationResume(applicationId)
      const url = URL.createObjectURL(response)
      const link = document.createElement('a')
      link.href = url
      link.download = fileName || 'resume'
      link.click()
      URL.revokeObjectURL(url)
    } catch (error) { setMessage(error?.message || 'Resume could not be downloaded.') }
  }

  if (role === 'industry' && view === 'postings') return <IndustryPostings />
  if (role === 'industry' && view === 'applicants') return <div className="workspace-page role-page"><header className="role-page-header"><div><span className="section-label">INDUSTRY APPLICANTS</span><h1>Application pipeline</h1><p>Review submitted student details, resumes, match insights, and decisions.</p></div><Users size={28} /></header>{message && <Alert type="info" message={message} />}<div className="role-table">{records.map((item) => <article className="role-row" key={item._id}><div><strong>{item.title}</strong><small>{item.type} · Review applications</small></div><Button size="sm" variant="outline" onClick={() => rankApplicants(item._id)}>View applicants</Button></article>)}</div><div className="candidate-list">{candidates.map((candidate) => <article className="candidate-row" key={candidate.applicationId}><div><strong>{candidate.applicant?.name || candidate.student?.name}</strong><small>{candidate.applicant?.email || candidate.student?.email} · {candidate.compatibility}% match</small><span>{candidate.applicant?.college || 'College not provided'} · Skills: {(candidate.applicant?.skills || candidate.student?.skills || []).join(', ') || 'None listed'}</span><span>Status: {candidate.status} · Applied {new Date(candidate.appliedAt).toLocaleDateString()}</span></div><div><Button size="sm" variant="outline" onClick={() => setSelectedCandidate(candidate)}>View</Button>{candidate.resume && <Button size="sm" variant="outline" onClick={() => downloadResume(candidate.applicationId, candidate.resume.originalName)}>Resume</Button>}{!['selected', 'rejected'].includes(candidate.status) && <><Button size="sm" variant="success" loading={loading} onClick={() => updateApplication(candidate.applicationId, 'selected')}><CheckCircle2 size={14} /> Accept</Button><Button size="sm" variant="danger" loading={loading} onClick={() => { setSelectedCandidate(candidate); setRejectionReason('') }}>Reject</Button></>}</div></article>)}</div>{selectedCandidate && <div className="application-review"><h2>Application details</h2><p><strong>{selectedCandidate.applicant?.name}</strong> · {selectedCandidate.applicant?.email}</p><p>{selectedCandidate.applicant?.college} · {selectedCandidate.applicant?.department} · Graduation {selectedCandidate.applicant?.graduationYear || 'Not provided'}</p><p>Skills: {(selectedCandidate.applicant?.skills || []).join(', ') || 'None listed'}</p><p>Match: {selectedCandidate.compatibility}% · {selectedCandidate.explanation}</p>{selectedCandidate.coverLetter && <p>Additional information: {selectedCandidate.coverLetter}</p>}{selectedCandidate.resume && <Button size="sm" variant="outline" onClick={() => downloadResume(selectedCandidate.applicationId, selectedCandidate.resume.originalName)}>Download {selectedCandidate.resume.originalName}</Button>}<div className="role-actions"><Button size="sm" variant="success" onClick={() => updateApplication(selectedCandidate.applicationId, 'selected')}>Confirm acceptance</Button><textarea value={rejectionReason} onChange={(event) => setRejectionReason(event.target.value)} placeholder="Reason for rejection" rows="3" /><Button size="sm" variant="danger" loading={loading} onClick={rejectSelected}>Reject with feedback</Button></div></div>}{!candidates.length && <p className="workspace-empty">Choose a posting to view its applications.</p>}</div>

  if (role === 'academician') return <div className="workspace-page role-page"><header className="role-page-header"><div><span className="section-label">ACADEMICIAN COLLABORATION</span><h1>My postings and collaborations</h1><p>Publish research, live projects, industrial training, and consultancy opportunities.</p></div><GraduationCap size={28} /></header>{message && <Alert type="info" message={message} />}<form className="role-form" onSubmit={publishOpportunity}><Input label="Posting title" name="title" value={form.title} onChange={update(setForm)} required placeholder="Computer Vision Research Project" /><Input label="Description" name="description" value={form.description} onChange={update(setForm)} required placeholder="Describe the research or industry collaboration" /><Input label="Required skills" name="requiredSkills" value={form.requiredSkills} onChange={update(setForm)} placeholder="Python, Research, Machine Learning" /><Input label="Location" name="location" value={form.location} onChange={update(setForm)} placeholder="University campus" /><Button type="submit" loading={loading}><Plus size={16} /> New academic posting</Button></form><div className="role-table">{records.map((item) => <article className="role-row" key={item._id || item.title}><div><strong>{item.title || item.type}</strong><small>{item.category || item.type || 'Academic-industry opportunity'}</small><span>{item.description || item.status || 'Available through the collaboration pipeline.'}</span></div><Button size="sm" variant="outline">View</Button></article>)}{!records.length && <p className="workspace-empty">No academic-industry opportunities yet.</p>}</div></div>

  if (role === 'institution') return <div className="workspace-page role-page"><header className="role-page-header"><div><span className="section-label">INSTITUTION ANALYTICS</span><h1>Monitor the whole ecosystem</h1><p>Live student, opportunity, application, skill-evidence, and AI matching metrics.</p></div><Search size={28} /></header><div className="role-stats">{Object.entries(records.totals || {}).map(([label, value]) => <article key={label}><strong>{value}</strong><span>{label}</span></article>)}<article><strong>{records.readiness || 0}%</strong><span>Assessment coverage</span></article><article><strong>{records.placementRate || 0}%</strong><span>Placement rate</span></article><article><strong>{records.matching?.averageMatch || 0}%</strong><span>Average AI match</span></article></div><section className="role-table"><h2>Top student skills</h2>{(records.topSkills || []).map((item) => <article className="role-row" key={item.skill}><div><strong>{item.skill}</strong><small>{item.count} evidence records</small></div><span>{item.averageScore ? `${item.averageScore}% average evidence` : 'Current demand signal'}</span></article>)}</section></div>

  return null
}