import React, { useEffect, useState } from 'react'
import { Save, Sparkles, Plus, Trash2 } from 'lucide-react'
import { Button, Alert, Input } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'

const SKILL_CATEGORIES = [
  ['programmingLanguages', 'Programming Languages', 'e.g. Python, JavaScript, Java'],
  ['frameworks', 'Frameworks', 'e.g. React, Node.js, Django'],
  ['libraries', 'Libraries', 'e.g. NumPy, Pandas, Lodash'],
  ['databases', 'Databases', 'e.g. MongoDB, PostgreSQL, Redis'],
  ['aiMl', 'AI / ML', 'e.g. TensorFlow, scikit-learn, Transformers'],
  ['webDev', 'Web Development', 'e.g. HTML, CSS, Tailwind'],
  ['cloud', 'Cloud', 'e.g. AWS, Azure, GCP'],
  ['devops', 'DevOps', 'e.g. Docker, Kubernetes, CI/CD'],
  ['cybersecurity', 'Cybersecurity', 'e.g. Network Security, OWASP'],
  ['tools', 'Tools', 'e.g. Git, Figma, Postman'],
]

const SkillCategoryField = ({ label, placeholder, value, onChange }) => {
  const skills = value || []
  const [draft, setDraft] = useState('')
  const add = () => {
    const trimmed = draft.trim()
    if (trimmed && !skills.includes(trimmed)) { onChange([...skills, trimmed]); setDraft('') }
  }
  const remove = (skill) => onChange(skills.filter((s) => s !== skill))
  return (
    <div className="profile-editor-skill-category">
      <label className="career-label">{label}</label>
      <div className="skill-tags" style={{ marginBottom: '8px' }}>
        {skills.map((s) => (
          <span key={s} className="skill-tag strong" style={{ cursor: 'pointer' }} onClick={() => remove(s)}>
            {s} <Trash2 size={10} />
          </span>
        ))}
        {skills.length === 0 && <span className="career-muted" style={{ fontSize: '12px' }}>None added yet</span>}
      </div>
      <div className="profile-editor-skill-add">
        <input
          className="linkedin-input"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); add() } }}
          placeholder={placeholder}
        />
        <button className="profile-editor-add-btn" onClick={add} type="button"><Plus size={14} /></button>
      </div>
    </div>
  )
}

const ExperienceForm = ({ items, onChange }) => {
  const empty = { organization: '', role: '', duration: '', responsibilities: [], technologies: [], achievements: [] }
  const update = (i, field, val) => { const updated = [...items]; updated[i] = { ...updated[i], [field]: val }; onChange(updated) }
  const remove = (i) => onChange(items.filter((_, idx) => idx !== i))
  return (
    <div className="profile-editor-list">
      {items.map((exp, i) => (
        <div key={i} className="profile-editor-item">
          <div className="profile-editor-item-header">
            <strong>Experience {i + 1}</strong>
            <button onClick={() => remove(i)} className="multi-resume-delete"><Trash2 size={14} /></button>
          </div>
          <div className="profile-form-grid-2">
            <Input label="Organization" value={exp.organization} onChange={(e) => update(i, 'organization', e.target.value)} placeholder="e.g. Google" />
            <Input label="Role" value={exp.role} onChange={(e) => update(i, 'role', e.target.value)} placeholder="e.g. ML Intern" />
          </div>
          <Input label="Duration" value={exp.duration} onChange={(e) => update(i, 'duration', e.target.value)} placeholder="e.g. June–Aug 2024" />
          <label className="career-label">Responsibilities (one per line)</label>
          <textarea className="linkedin-textarea" rows={3} value={(exp.responsibilities || []).join('\n')}
            onChange={(e) => update(i, 'responsibilities', e.target.value.split('\n').filter(Boolean))}
            placeholder="e.g. Built a recommendation engine using Python and scikit-learn" />
          <label className="career-label">Technologies</label>
          <input className="linkedin-input" value={(exp.technologies || []).join(', ')}
            onChange={(e) => update(i, 'technologies', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
            placeholder="e.g. Python, TensorFlow, Flask" />
          <label className="career-label">Achievements</label>
          <input className="linkedin-input" value={(exp.achievements || []).join(', ')}
            onChange={(e) => update(i, 'achievements', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
            placeholder="e.g. Reduced model inference time by 30%" />
        </div>
      ))}
      <Button variant="outline" size="sm" onClick={() => onChange([...items, { ...empty }])}>
        <Plus size={13} /> Add Experience
      </Button>
    </div>
  )
}

const ProjectForm = ({ items, onChange }) => {
  const empty = { name: '', problemStatement: '', solution: '', technologies: [], contribution: '', teamSize: 1, duration: '', github: '', liveDemo: '', impact: '' }
  const update = (i, field, val) => { const updated = [...items]; updated[i] = { ...updated[i], [field]: val }; onChange(updated) }
  const remove = (i) => onChange(items.filter((_, idx) => idx !== i))
  return (
    <div className="profile-editor-list">
      {items.map((proj, i) => (
        <div key={i} className="profile-editor-item">
          <div className="profile-editor-item-header">
            <strong>Project {i + 1}{proj.name ? ` — ${proj.name}` : ''}</strong>
            <button onClick={() => remove(i)} className="multi-resume-delete"><Trash2 size={14} /></button>
          </div>
          <div className="profile-form-grid-2">
            <Input label="Project Name" value={proj.name} onChange={(e) => update(i, 'name', e.target.value)} placeholder="e.g. Resume Skill Extractor" />
            <Input label="Duration" value={proj.duration} onChange={(e) => update(i, 'duration', e.target.value)} placeholder="e.g. 2 weeks" />
          </div>
          <label className="career-label">Problem Statement</label>
          <textarea className="linkedin-textarea" rows={2} value={proj.problemStatement}
            onChange={(e) => update(i, 'problemStatement', e.target.value)}
            placeholder="What problem does this project solve?" />
          <label className="career-label">Solution</label>
          <textarea className="linkedin-textarea" rows={2} value={proj.solution}
            onChange={(e) => update(i, 'solution', e.target.value)}
            placeholder="How did you solve it?" />
          <label className="career-label">Technologies (comma-separated)</label>
          <input className="linkedin-input" value={(proj.technologies || []).join(', ')}
            onChange={(e) => update(i, 'technologies', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
            placeholder="e.g. Python, FastAPI, React" />
          <div className="profile-form-grid-2">
            <Input label="Your Contribution" value={proj.contribution} onChange={(e) => update(i, 'contribution', e.target.value)} placeholder="e.g. Full individual project" />
            <Input label="Team Size" type="number" value={proj.teamSize} onChange={(e) => update(i, 'teamSize', parseInt(e.target.value) || 1)} />
          </div>
          <div className="profile-form-grid-2">
            <Input label="GitHub URL" value={proj.github} onChange={(e) => update(i, 'github', e.target.value)} placeholder="https://github.com/..." />
            <Input label="Live Demo URL" value={proj.liveDemo} onChange={(e) => update(i, 'liveDemo', e.target.value)} placeholder="https://..." />
          </div>
          <label className="career-label">Results / Impact</label>
          <input className="linkedin-input" value={proj.impact}
            onChange={(e) => update(i, 'impact', e.target.value)}
            placeholder="e.g. Deployed on AWS, 200+ users, won hackathon" />
        </div>
      ))}
      <Button variant="outline" size="sm" onClick={() => onChange([...items, { ...empty }])}>
        <Plus size={13} /> Add Project
      </Button>
    </div>
  )
}

