const AchievementForm = ({ items, onChange }) => {
  const empty = { title: '', description: '', category: 'hackathon' }
  const update = (i, field, val) => { const updated = [...items]; updated[i] = { ...updated[i], [field]: val }; onChange(updated) }
  const remove = (i) => onChange(items.filter((_, idx) => idx !== i))
  const CATS = ['hackathon', 'award', 'competition', 'leadership', 'publication', 'opensource', 'scholarship', 'other']
  return (
    <div className="profile-editor-list">
      {items.map((ach, i) => (
        <div key={i} className="profile-editor-item">
          <div className="profile-editor-item-header">
            <strong>Achievement {i + 1}</strong>
            <button onClick={() => remove(i)} className="multi-resume-delete"><Trash2 size={14} /></button>
          </div>
          <div className="profile-form-grid-2">
            <Input label="Title" value={ach.title} onChange={(e) => update(i, 'title', e.target.value)} placeholder="e.g. National Hackathon Finalist" />
            <div>
              <label className="career-label">Category</label>
              <select className="linkedin-input" value={ach.category} onChange={(e) => update(i, 'category', e.target.value)}>
                {CATS.map((c) => <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>)}
              </select>
            </div>
          </div>
          <label className="career-label">Description</label>
          <textarea className="linkedin-textarea" rows={2} value={ach.description}
            onChange={(e) => update(i, 'description', e.target.value)}
            placeholder="Brief description of the achievement" />
        </div>
      ))}
      <Button variant="outline" size="sm" onClick={() => onChange([...items, { ...empty }])}>
        <Plus size={13} /> Add Achievement
      </Button>
    </div>
  )
}

export const CareerProfileEditor = () => {
  const [form, setForm] = useState({
    linkedin: '', github: '', portfolio: '',
    currentYear: '', currentSemester: '', relevantCoursework: [],
    skillsByCategory: { programmingLanguages: [], frameworks: [], libraries: [], databases: [], aiMl: [], webDev: [], cloud: [], devops: [], cybersecurity: [], tools: [] },
    experience: [], projects: [], certifications: [], achievements: [],
    targetRoles: [], preferredLocations: [],
  })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')
  const [activeSection, setActiveSection] = useState('links')

  useEffect(() => {
    careerAgentAPI.getProfile()
      .then((res) => {
        const cp = res?.data?.bundle?.careerProfile || {}
        const user = res?.data?.bundle?.user || {}
        const portfolio = res?.data?.bundle?.portfolio || {}
        setForm((prev) => ({
          ...prev,
          linkedin: cp.linkedin || portfolio.linkedin || '',
          github: cp.github || portfolio.github || '',
          portfolio: cp.portfolio || portfolio.website || '',
          currentYear: cp.currentYear || '',
          currentSemester: cp.currentSemester || '',
          relevantCoursework: cp.relevantCoursework || [],
          skillsByCategory: cp.skillsByCategory || prev.skillsByCategory,
          experience: cp.experience || [],
          projects: cp.projects || [],
          certifications: cp.certifications || [],
          achievements: cp.achievements || [],
          targetRoles: cp.targetRoles || [],
          preferredLocations: cp.preferredLocations || [],
        }))
      })
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [])

  const updateField = (field, value) => setForm((prev) => ({ ...prev, [field]: value }))
  const updateSkillCat = (cat, value) => setForm((prev) => ({ ...prev, skillsByCategory: { ...prev.skillsByCategory, [cat]: value } }))

  const save = async () => {
    setSaving(true)
    setMessage('')
    setError('')
    try {
      await careerAgentAPI.saveProfile(form)
      setMessage('Career profile saved successfully. Your scores will update on next analysis.')
    } catch (err) {
      setError(err?.message || 'Could not save profile.')
    } finally {
      setSaving(false)
    }
  }

  const SECTIONS = [
    { id: 'links', label: 'Links & Goals' },
    { id: 'education', label: 'Education' },
    { id: 'skills', label: 'Skills' },
    { id: 'experience', label: 'Experience' },
    { id: 'projects', label: 'Projects' },
    { id: 'certifications', label: 'Certifications' },
    { id: 'achievements', label: 'Achievements' },
  ]

  if (loading) return <div className="career-loading"><Sparkles size={18} /> Loading your career profile...</div>

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">CAREER PROFILE EDITOR</span>
        <h2>Update your master career profile</h2>
        <p className="career-muted">
          All information you enter here is used to generate your ATS resume, skill gap analysis, and internship matches.
          Only enter information you genuinely have — do not fabricate experience or metrics.
        </p>
      </div>

      {/* Section nav */}
      <div className="profile-editor-nav">
        {SECTIONS.map(({ id, label }) => (
          <button key={id} className={`profile-editor-nav-btn ${activeSection === id ? 'active' : ''}`} onClick={() => setActiveSection(id)}>
            {label}
          </button>
        ))}
      </div>

      <div className="profile-editor-body">
        {/* Links & Goals */}
        {activeSection === 'links' && (
          <div className="profile-editor-section">
            <Input label="LinkedIn URL" value={form.linkedin} onChange={(e) => updateField('linkedin', e.target.value)} placeholder="https://linkedin.com/in/your-profile" />
            <Input label="GitHub URL" value={form.github} onChange={(e) => updateField('github', e.target.value)} placeholder="https://github.com/your-username" />
            <Input label="Portfolio / Website" value={form.portfolio} onChange={(e) => updateField('portfolio', e.target.value)} placeholder="https://yourportfolio.dev" />
            <label className="career-label">Target Roles (comma-separated)</label>
            <input className="linkedin-input" value={(form.targetRoles || []).join(', ')}
              onChange={(e) => updateField('targetRoles', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
              placeholder="e.g. AI/ML Engineer, Data Scientist" />
            <label className="career-label">Preferred Locations (comma-separated)</label>
            <input className="linkedin-input" value={(form.preferredLocations || []).join(', ')}
              onChange={(e) => updateField('preferredLocations', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
              placeholder="e.g. Bengaluru, Remote, Mumbai" />
          </div>
        )}

        {/* Education */}
        {activeSection === 'education' && (
          <div className="profile-editor-section">
            <div className="profile-form-grid-2">
              <Input label="Current Year" type="number" value={form.currentYear}
                onChange={(e) => updateField('currentYear', e.target.value ? parseInt(e.target.value) : '')}
                placeholder="e.g. 3" />
              <Input label="Current Semester" type="number" value={form.currentSemester}
                onChange={(e) => updateField('currentSemester', e.target.value ? parseInt(e.target.value) : '')}
                placeholder="e.g. 6" />
            </div>
            <label className="career-label">Relevant Coursework (comma-separated)</label>
            <textarea className="linkedin-textarea" rows={3}
              value={(form.relevantCoursework || []).join(', ')}
              onChange={(e) => updateField('relevantCoursework', e.target.value.split(',').map((s) => s.trim()).filter(Boolean))}
              placeholder="e.g. Data Structures, Machine Learning, Database Management" />
          </div>
        )}

        {/* Skills */}
        {activeSection === 'skills' && (
          <div className="profile-editor-section">
            <p className="career-muted">Click on a skill tag to remove it. Press Enter or click + to add a skill.</p>
            {SKILL_CATEGORIES.map(([key, label, placeholder]) => (
              <SkillCategoryField
                key={key}
                label={label}
                placeholder={placeholder}
                value={form.skillsByCategory[key]}
                onChange={(val) => updateSkillCat(key, val)}
              />
            ))}
          </div>
        )}

        {/* Experience */}
        {activeSection === 'experience' && (
          <div className="profile-editor-section">
            <ExperienceForm items={form.experience} onChange={(val) => updateField('experience', val)} />
          </div>
        )}

        {/* Projects */}
        {activeSection === 'projects' && (
          <div className="profile-editor-section">
            <ProjectForm items={form.projects} onChange={(val) => updateField('projects', val)} />
          </div>
        )}

        {/* Certifications */}
        {activeSection === 'certifications' && (
          <div className="profile-editor-section">
            <CertForm items={form.certifications} onChange={(val) => updateField('certifications', val)} />
          </div>
        )}

        {/* Achievements */}
        {activeSection === 'achievements' && (
          <div className="profile-editor-section">
            <AchievementForm items={form.achievements} onChange={(val) => updateField('achievements', val)} />
          </div>
        )}
      </div>

      {/* Save */}
      {message && <Alert type="success" message={message} />}
      {error && <Alert type="error" message={error} />}
      <div className="profile-editor-footer">
        <Button variant="nav" onClick={save} loading={saving}>
          <Save size={15} /> Save Career Profile
        </Button>
      </div>
    </div>
  )
}
