import React from 'react'
import { useAuth } from '../context/AuthContext'
import { StudentDashboard } from './student/Dashboard'
import { IndustryDashboard } from './industry/Dashboard'
import { AcademicianDashboard } from './academician/Dashboard'
import { InstitutionDashboard } from './institution/Dashboard'

const dashboards = {
  student: StudentDashboard,
  industry: IndustryDashboard,
  academician: AcademicianDashboard,
  institution: InstitutionDashboard,
}

export const DashboardPage = () => {
  const { user } = useAuth()
  const Dashboard = dashboards[user?.role] || StudentDashboard
  return <Dashboard user={user} />
}
