// Validation helpers
export const validateEmail = (email) => {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  return regex.test(email)
}

export const validateOTP = (otp) => {
  return /^\d{6}$/.test(otp)
}

export const validatePassword = (password) => {
  return password.length >= 8
}

// Storage helpers
export const setToken = (token, type = 'access') => {
  localStorage.setItem(`${type}Token`, token)
}

export const getToken = (type = 'access') => {
  return localStorage.getItem(`${type}Token`)
}

export const clearTokens = () => {
  localStorage.removeItem('accessToken')
  localStorage.removeItem('refreshToken')
  localStorage.removeItem('user')
}

// Formatting helpers
export const formatDate = (date) => {
  return new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

export const formatTime = (date) => {
  return new Date(date).toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
  })
}

export const formatDateTime = (date) => {
  return `${formatDate(date)} ${formatTime(date)}`
}

// Error message helpers
export const getErrorMessage = (error) => {
  if (!error) return 'An error occurred. Please try again.'
  if (typeof error === 'string') return error
  if (error?.response?.data?.message) return error.response.data.message
  if (error?.response?.data?.error) return error.response.data.error
  if (error?.data?.message) return error.data.message
  if (error?.data?.error) return error.data.error
  if (error?.data?.errors?.[0]) return error.data.errors[0]
  if (error?.message) return error.message
  if (typeof error?.response?.data === 'string') return error.response.data
  return 'Invalid credentials. Please check your email and password.'
}

// Array helpers
export const unique = (arr) => [...new Set(arr)]

export const groupBy = (arr, key) => {
  return arr.reduce((result, item) => {
    const group = item[key]
    if (!result[group]) result[group] = []
    result[group].push(item)
    return result
  }, {})
}

// String helpers
export const capitalize = (str) => {
  return str.charAt(0).toUpperCase() + str.slice(1)
}

export const truncate = (str, length = 50) => {
  return str.length > length ? str.substring(0, length) + '...' : str
}

// Number helpers
export const formatNumber = (num) => {
  return new Intl.NumberFormat('en-US').format(num)
}

export const formatPercent = (num, decimals = 0) => {
  return `${(num * 100).toFixed(decimals)}%`
}
